using System;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Mewgic;
public static class Part12CEditor
{
 public static void DiskCheck(){UnityEditor.AssetDatabase.ImportAsset("Assets/Localization/LocalizationSettings.asset",UnityEditor.ImportAssetOptions.ForceUpdate|UnityEditor.ImportAssetOptions.ForceSynchronousImport);Part12CLocalization.Validate();}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Önce Play Mode durdurulmalı");DiskCheck();GameplayBoosterTests.ModelTests();SessionState.SetString("Part12C.Key","Mewgic.Tests.Part12C."+Guid.NewGuid().ToString("N"));EditorSceneManager.OpenScene("Assets/Scenes/Home.unity");new GameObject("PART12C QA").AddComponent<Part12CProbe>();Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}
 public static void Reload(){if(EditorApplication.isPlaying)throw new Exception("Önce Play Mode durdurulmalı");DiskCheck();EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity");new GameObject("PART12C Reload QA").AddComponent<Part12CProbe>().reload=true;Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}
 public static void Compatibility(){string key="Mewgic.Tests.Part12C.Legacy."+Guid.NewGuid().ToString("N");var checks=new System.Collections.Generic.List<string>();try{var d=new Mewgic.Core.ProgressData();d.presentation.coins=77;d.levels.Add(new Mewgic.Core.LevelRecord{level=1,bestStars=2,rewardClaimed=true});var old=Newtonsoft.Json.Linq.JObject.Parse(JsonUtility.ToJson(d));((Newtonsoft.Json.Linq.JObject)old["presentation"]).Remove("manualLocale");PlayerPrefs.SetString(key,old.ToString());var ledger=GameplayProgress.Open(key);if(ledger.Presentation.manualLocale!=null||ledger.Presentation.coins!=77||ledger.BestStars(1)!=2)throw new Exception("Eski kayıt uyumu");checks.Add("manualLocale alanı olmayan gerçek eski JSON korunur");if(!ledger.SetManualLocale("pt-BR"))throw new Exception("Dil kaydı");var reload=GameplayProgress.Open(key);if(reload.Presentation.manualLocale!="pt-BR"||reload.Presentation.coins!=77||reload.BestStars(1)!=2)throw new Exception("Dil yeniden açılışı");checks.Add("Eski kayda dil ekleme ve yeniden açılış para/yıldızı korur");var fresh=GameplayProgress.Open(key+".new");if(fresh.Presentation.manualLocale!=null||fresh.Snapshot.levels.Count!=0)throw new Exception("Yeni kayıt");checks.Add("Yeni kullanıcıda manuel tercih yok, cihaz seçicisi kullanılabilir");System.IO.File.WriteAllText("docs/ProductionReports/Part12C/COMPATIBILITY.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=true,checks},Newtonsoft.Json.Formatting.Indented));}finally{foreach(string suffix in new[]{"",".backup",".corrupt",".new"})PlayerPrefs.DeleteKey(key+suffix);PlayerPrefs.Save();}}
 public static void Preview(){if(EditorApplication.isPlaying)throw new Exception("Önce Play Mode durdurulmalı");DiskCheck();EditorSceneManager.OpenScene("Assets/Scenes/Home.unity");new GameObject("PART12C Safe Preview").AddComponent<Part12CProbe>().preview=true;Part12BEditor.Size(1600);EditorApplication.isPlaying=true;}

}
